import test from 'node:test';
import assert from 'node:assert/strict';
import { expectOk, classesEqual, classDiff } from '../fixtures/premise.mjs';
import { layoutOf, readGolden, cellArgs, deviceOf } from '../fixtures/lanes.mjs';
import { recorder } from '../src/spans.mjs';

// The decisions are Lean's (Fw.Measure.WktrLayout); the golden vectors are generated by lean/scripts/WktrFixturesGolden.lean.
const lines = readGolden();
const of = (k) => lines.filter((l) => l.kind === k);

test('golden: expectCase lines replay through expectOk', () => {
  const cases = of('expectCase');
  assert.ok(cases.length >= 60);
  for (const c of cases) assert.equal(expectOk(c.expect, c.observedClass, c.sums), c.ok, `${c.name} ${JSON.stringify(c.expect)}`);
  assert.ok(cases.some((c) => c.ok) && cases.some((c) => !c.ok));
});

test('golden: classesEqualCase lines replay through classesEqual', () => {
  const cases = of('classesEqualCase');
  assert.ok(cases.length >= 6);
  for (const c of cases) assert.equal(classesEqual(c.a, c.b), c.equal, c.name);
  assert.deepEqual(classDiff({ a: { class: 'deterministic' } }, { a: { class: 'stable' }, b: { class: 'deterministic' } }), ['a', 'b']);
});

test('golden: every layout runs each of the 13 cells once, widths up to 3, one phase per variant', () => {
  const cells = of('cells')[0].cells;
  assert.equal(cells.length, 13);
  const key = (c) => `${c.fixture}-f${c.frames}-${c.variant}`;
  for (const l of of('layout')) {
    assert.deepEqual(l.phases.map((p) => p.variant), ['live', 'live-trace']);
    const seen = l.phases.flatMap((p) => { assert.ok(p.width >= 1 && p.width <= 3 && p.lanes.length === p.width); return p.lanes.flat(); });
    assert.deepEqual(seen.map(key).sort(), cells.map(key).sort(), `${l.mode} ${l.req}`);
    for (const p of l.phases) assert.ok(p.lanes.flat().every((c) => c.variant === p.variant));
  }
  // the premise test asks for widths 1, 2, 3; the production layout (nothing proved yet) is serial
  assert.deepEqual(of('layout').filter((l) => l.mode === 'probe').map((l) => l.phases.map((p) => p.width)), [[1, 1], [2, 2], [3, 3]]);
});

test('golden: maxParallel keeps the slots of webkit-sim and gate-gaps', () => {
  for (const l of of('maxParallel')) {
    assert.ok(l.maxParallel >= 1 && l.maxParallel <= Math.max(1, l.jobs));
    assert.ok(l.maxParallel + l.others.reduce((a, b) => a + b, 0) <= l.slots);
  }
});

test('lanes: layoutOf picks the golden line; cellArgs names the lane device', () => {
  assert.equal(layoutOf(lines, 'probe', 2).phases[0].width, 2);
  assert.throws(() => layoutOf(lines, 'probe', 9));
  const a = cellArgs({ root: '/r', out: '/o', passes: 3, cell: { fixture: 'control', frames: 3, variant: 'live' }, lane: 2 });
  assert.equal(a[a.indexOf('--device-name') + 1], 'fw-wktr-2');
  assert.equal(a[a.indexOf('--frames') + 1], '3');
  assert.equal(a[a.indexOf('--variants') + 1], 'live');
  assert.equal(deviceOf(0), 'fw-wktr');
});

test('spans: the recorder books the time since the previous mark under each name', async () => {
  const r = recorder();
  await new Promise((ok) => setTimeout(ok, 20));
  r.mark('a');
  r.mark('a');
  const s = r.spans();
  assert.ok(s.a >= 15 && s.a < 500);
});
